#include <cmath>
#include <algorithm>
#include <array>
#include <vector>
#include <stdexcept>
#include <iostream>
#ifdef __CUDACC__
#include <cuda_runtime.h>
#endif
extern "C" {
constexpr int N_STATE = 8;
constexpr double L_FAST = 6.0;
constexpr double EPS_VAL = 1e-3;
constexpr double ATOL_VAL = 1e-12;
constexpr double INV_SQRT_8 = 0.35355339059327373;
typedef struct {
double d;

 double chi;
double Is;
double ceil_val;
double fwd;
double ret;
double amort;
double x[N_STATE];
} SolvencyStateCPU;
void init_cpu_node(SolvencyStateCPU* node, double d, double chi) {
node->d = d;
node->chi = std::clamp(chi, 1e-4, 0.25);
node->Is = 8.0 * node->chi;
node->ceil_val = (node->Is > 0.0) ? (node->d / node->Is) : 0.0;
node->fwd = 0.0;
node->ret = 0.0;
node->amort = 0.0;
for (int i = 0; i < N_STATE; ++i) {
node->x[i] = 0.0;
}
}
typedef struct {
double grant;
double interior;
double claimed;
double claimable;
double fast;
double slow;
int solvent;
} StepResultCPU;
StepResultCPU step_cpu_node(SolvencyStateCPU* node, double request, double dt) {
double sum = 0.0;
for (int i = 0; i < N_STATE; ++i) sum += node->x[i];
double s_curr = sum * INV_SQRT_8;
double e_mean = s_curr * INV_SQRT_8;

 double ef = std::exp(-L_FAST * dt);
double es = std::exp(-node->Is * dt);
double s_next = node->ceil_val + (s_curr - node->ceil_val) * es;
double e_next = s_next * INV_SQRT_8;
double fast_sq = 0.0;
for (int i = 0; i < N_STATE; ++i) {
double r_i = node->x[i] - e_mean;
node->x[i] = r_i * ef + e_next;
double r_next = node->x[i] - e_next;
fast_sq += r_next * r_next;
}
double fast_val = std::sqrt(fast_sq);
double post_interior = std::max(0.0, node->ceil_val - s_next);
double cur_claimed = node->fwd - node->ret - node->amort;
double excess = cur_claimed - post_interior;
if (excess > 0.0) {
node->amort += excess;
cur_claimed = node->fwd - node->ret - node->amort;
}
int is_solvent = (cur_claimed <= post_interior + ATOL_VAL) ? 1 : 0;
double granted = 0.0;
if (request > 0.0 && fast_val < EPS_VAL) {
double claimable = std::max(0.0, post_interior - cur_claimed);
granted = std::min(request, claimable);
node->fwd += granted;
cur_claimed = node->fwd - node->ret - node->amort;
}
return {
granted,
post_interior,
cur_claimed,

 std::max(0.0, post_interior - cur_claimed),
fast_val,
s_next,
is_solvent
};
}
} // extern "C"

